// Chai Pot for SHGs: Savings-pot manager for women's self-help groups in India
// Zero dependencies. Tests: npm test (node --experimental-strip-types --test).
// First draft generated by AgentFoundry SMART-Code (see chaipot/cfi/af-sessions), reviewed + fixed by hand.

// ===== TYPES =====

type Role = "leader" | "treasurer" | "member";

type Member = {
  id: string;
  name: string;
  nameHi: string;
  role: Role;
  joined: string; // "YYYY-MM"
};

type Rules = {
  monthlySaving: number; // rupees
  interestPctPerMonth: number; // 1 = 1% on outstanding principal
  maxLoanMultiple: number; // loan <= this × own savings
  maxLoanPctOfCash: number; // one loan <= this % of cash in hand
  minMonthsMember: number; // months before eligible to borrow
  maxTenureMonths: number; // maximum loan repayment months
  approvalsNeeded: number; // distinct leader/treasurer approvals to disburse
};

type EvBase = {
  id: string;
  at: string; // ISO 8601
  by: string; // member id who recorded it
  month: string; // "YYYY-MM"
};

type Ev =
  | (EvBase & {
      type: "contribution";
      memberId: string;
      amount: number;
    })
  | (EvBase & {
      type: "loan_request";
      loanId: string;
      memberId: string;
      amount: number;
      tenureMonths: number;
      purpose: string;
    })
  | (EvBase & {
      type: "loan_approve";
      loanId: string;
    })
  | (EvBase & {
      type: "loan_reject";
      loanId: string;
      reason: string;
    })
  | (EvBase & {
      type: "repayment";
      loanId: string;
      amount: number;
    });

type Group = {
  id: string;
  name: string;
  village: string;
  rules: Rules;
  members: Member[];
  events: Ev[];
};

type LoanView = {
  loanId: string;
  memberId: string;
  amount: number;
  tenureMonths: number;
  purpose: string;
  status: "pending" | "approved" | "rejected" | "closed";
  approvals: string[]; // member ids of approvers
  principalOutstanding: number;
  interestPaid: number;
  nextDue: { principal: number; interest: number; total: number } | null;
};

type ComputedState = {
  cash: number;
  totalSavings: number;
  interestEarned: number;
  members: Record<
    string,
    { savings: number; paidThisMonth: boolean; monthsMissed: number }
  >;
  loans: LoanView[];
};

type CheckLoanResult = {
  ok: boolean;
  maxEligible: number;
  problems: Array<{ code: string; en: string; hi: string }>;
  plan: Array<{ n: number; principal: number; interest: number; total: number }>;
};

// ===== HELPERS =====

/** Whole months from a to b (b - a). Both "YYYY-MM" strings. */
function monthsBetween(a: string, b: string): number {
  const [ya, ma] = a.split("-").map(Number);
  const [yb, mb] = b.split("-").map(Number);
  return (yb - ya) * 12 + (mb - ma);
}

/** Format rupees with Indian grouping: 150000 -> "₹1,50,000". */
function inr(n: number): string {
  const sign = n < 0 ? "-" : "";
  const digits = String(Math.round(Math.abs(n)));
  const last3 = digits.slice(-3);
  const rest = digits.slice(0, -3).replace(/\B(?=(\d{2})+(?!\d))/g, ",");
  return sign + "₹" + (rest ? rest + "," + last3 : last3);
}

/** "YYYY-MM" plus k months. */
function addMonths(m: string, k: number): string {
  const [y, mo] = m.split("-").map(Number);
  const t = y * 12 + (mo - 1) + k;
  return `${Math.floor(t / 12)}-${String((t % 12) + 1).padStart(2, "0")}`;
}

const isOfficer = (g: Group, id: string) => g.members.some((m) => m.id === id && (m.role === "leader" || m.role === "treasurer"));

/** Compute the pot's state as of `month` by replaying the event log in order. */
function computeState(g: Group, month: string): ComputedState {
  type L = Omit<LoanView, "nextDue"> & { interestMonth: string };
  const loanMap = new Map<string, L>();
  const savings: Record<string, number> = {};
  const paidMonths: Record<string, Set<string>> = {};
  let cash = 0;
  let interestEarned = 0;
  const rate = g.rules.interestPctPerMonth;
  g.members.forEach((m) => { savings[m.id] = 0; paidMonths[m.id] = new Set(); });

  for (const ev of g.events) {
    if (monthsBetween(ev.month, month) < 0) continue; // event is after `month`
    if (ev.type === "contribution") {
      if (!(ev.memberId in savings)) continue;
      savings[ev.memberId] += ev.amount;
      paidMonths[ev.memberId].add(ev.month);
      cash += ev.amount;
    } else if (ev.type === "loan_request") {
      loanMap.set(ev.loanId, { loanId: ev.loanId, memberId: ev.memberId, amount: ev.amount, tenureMonths: ev.tenureMonths,
        purpose: ev.purpose, status: "pending", approvals: [], principalOutstanding: ev.amount, interestPaid: 0, interestMonth: "" });
    } else if (ev.type === "loan_approve") {
      const loan = loanMap.get(ev.loanId);
      // Only officers count, never the borrower, never twice.
      if (!loan || loan.status !== "pending" || !isOfficer(g, ev.by) || ev.by === loan.memberId || loan.approvals.includes(ev.by)) continue;
      loan.approvals.push(ev.by);
      if (loan.approvals.length >= g.rules.approvalsNeeded) {
        loan.status = "approved";
        cash -= loan.amount; // disbursed the moment it is approved
      }
    } else if (ev.type === "loan_reject") {
      const loan = loanMap.get(ev.loanId);
      if (loan && loan.status === "pending") loan.status = "rejected";
    } else if (ev.type === "repayment") {
      const loan = loanMap.get(ev.loanId);
      if (!loan || loan.status !== "approved") continue;
      // Interest for the month is charged once, on the first repayment of that month, and paid first.
      let interest = 0;
      if (loan.interestMonth !== ev.month) {
        interest = Math.min(ev.amount, Math.round((loan.principalOutstanding * rate) / 100));
        loan.interestMonth = ev.month;
      }
      const toPrincipal = Math.min(ev.amount - interest, loan.principalOutstanding);
      loan.principalOutstanding -= toPrincipal;
      loan.interestPaid += interest;
      interestEarned += interest;
      cash += interest + toPrincipal;
      if (loan.principalOutstanding === 0) loan.status = "closed";
    }
  }

  const members: ComputedState["members"] = {};
  for (const m of g.members) {
    const span = monthsBetween(m.joined, month) + 1;
    let missed = 0;
    for (let i = 0; i < span; i++) if (!paidMonths[m.id].has(addMonths(m.joined, i))) missed++;
    members[m.id] = { savings: savings[m.id], paidThisMonth: paidMonths[m.id].has(month), monthsMissed: missed };
  }

  const loans: LoanView[] = Array.from(loanMap.values()).map(({ interestMonth, ...loan }) => {
    let nextDue: LoanView["nextDue"] = null;
    if (loan.status === "approved") {
      const principal = Math.min(loan.principalOutstanding, Math.ceil(loan.amount / loan.tenureMonths));
      const interest = interestMonth === month ? 0 : Math.round((loan.principalOutstanding * rate) / 100);
      nextDue = { principal, interest, total: principal + interest };
    }
    return { ...loan, nextDue };
  });

  const totalSavings = Object.values(savings).reduce((a, b) => a + b, 0);
  return { cash, totalSavings, interestEarned, members, loans };
}

/** Check if a loan is valid and return plan. */
function checkLoan(
  g: Group,
  memberId: string,
  amount: number,
  tenureMonths: number,
  month: string
): CheckLoanResult {
  const problems: CheckLoanResult["problems"] = [];
  const member = g.members.find((m) => m.id === memberId);
  if (!member) {
    problems.push({
      code: "unknown_member",
      en: `Member ${memberId} not found.`,
      hi: `सदस्य ${memberId} नहीं मिली।`,
    });
    return { ok: false, maxEligible: 0, problems, plan: [] };
  }

  if (amount <= 0) {
    problems.push({
      code: "bad_amount",
      en: "Loan amount must be positive.",
      hi: "उधार की रकम सकारात्मक होनी चाहिए।",
    });
  }

  const state = computeState(g, month);
  const memberState = state.members[memberId];
  const savings = memberState?.savings || 0;
  const monthsAsMember = monthsBetween(member.joined, month) + 1;

  if (monthsAsMember < g.rules.minMonthsMember) {
    problems.push({
      code: "too_new",
      en: `${member.name} has been a member for ${monthsAsMember} months; needs ${g.rules.minMonthsMember}.`,
      hi: `${member.nameHi} ${monthsAsMember} महीने से सदस्य हैं; उधार के लिए ${g.rules.minMonthsMember} महीने ज़रूरी हैं।`,
    });
  }

  const openLoan = state.loans.find(
    (l) => l.memberId === memberId && (l.status === "pending" || l.status === "approved")
  );
  if (openLoan) {
    problems.push({
      code: "open_loan",
      en: `${member.name} already has an open loan (${openLoan.loanId}).`,
      hi: `${member.nameHi} के पास पहले से एक खुला उधार है (${openLoan.loanId})।`,
    });
  }

  if (memberState && memberState.monthsMissed > 0) {
    problems.push({
      code: "dues_unpaid",
      en: `${member.name} has missed ${memberState.monthsMissed} payment(s).`,
      hi: `${member.nameHi} ने ${memberState.monthsMissed} भुगतान छोड़े हैं।`,
    });
  }

  if (tenureMonths < 1 || tenureMonths > g.rules.maxTenureMonths) {
    problems.push({
      code: "bad_tenure",
      en: `Tenure must be 1–${g.rules.maxTenureMonths} months.`,
      hi: `कार्यकाल 1–${g.rules.maxTenureMonths} महीने होना चाहिए।`,
    });
  }

  const byMultiple = Math.floor(savings * g.rules.maxLoanMultiple);
  const byCash = Math.floor((state.cash * g.rules.maxLoanPctOfCash) / 100);
  const maxEligible = Math.floor(Math.max(0, Math.min(byMultiple, byCash)) / 100) * 100;

  if (amount > byMultiple) {
    problems.push({
      code: "over_multiple",
      en: `${member.name} can borrow up to ${inr(byMultiple)} (${g.rules.maxLoanMultiple}× savings of ${inr(savings)}).`,
      hi: `${member.nameHi} ${inr(byMultiple)} तक उधार ले सकती हैं (अपनी बचत ${inr(savings)} का ${g.rules.maxLoanMultiple} गुना)।`,
    });
  }

  if (amount > byCash) {
    problems.push({
      code: "over_cash",
      en: `Loan would exceed ${g.rules.maxLoanPctOfCash}% of available cash (${inr(byCash)}).`,
      hi: `उधार उपलब्ध नकद का ${g.rules.maxLoanPctOfCash}% (${inr(byCash)}) से अधिक है।`,
    });
  }

  // Build repayment plan
  const plan: CheckLoanResult["plan"] = [];
  if (amount <= 0 || tenureMonths < 1) return { ok: false, maxEligible, problems, plan };
  const principalPerMonth = Math.ceil(amount / tenureMonths);
  let remaining = amount;
  for (let i = 1; i <= tenureMonths; i++) {
    const principal = Math.min(remaining, principalPerMonth);
    const interest = Math.round((remaining * g.rules.interestPctPerMonth) / 100);
    plan.push({ n: i, principal, interest, total: principal + interest });
    remaining -= principal;
  }

  return {
    ok: problems.length === 0,
    maxEligible,
    problems,
    plan,
  };
}

/** Short text for a member's balance. */
function balanceText(g: Group, memberId: string, month: string, lang: "en" | "hi"): string {
  const member = g.members.find((m) => m.id === memberId);
  if (!member) return lang === "en" ? "Member not found." : "सदस्य नहीं मिली।";

  const state = computeState(g, month);
  const memberState = state.members[memberId];
  if (!memberState) return lang === "en" ? "No data." : "कोई डेटा नहीं।";

  const name = lang === "en" ? member.name : member.nameHi;
  const savings = memberState.savings;
  const paid = memberState.paidThisMonth;
  const paidText = lang === "en" ? (paid ? "paid ✓" : "not yet paid") : paid ? "दिया गया ✓" : "अभी नहीं";
  
  const loan = state.loans.find((l) => l.memberId === memberId && l.status === "approved");
  const loanText = loan
    ? lang === "en"
      ? `Loan left: ${inr(loan.principalOutstanding)}. Next payment: ${inr(loan.nextDue?.total ?? 0)}.`
      : `उधार बाकी: ${inr(loan.principalOutstanding)}। अगली किस्त: ${inr(loan.nextDue?.total ?? 0)}।`
    : lang === "en" ? "No loan." : "कोई उधार नहीं।";

  return lang === "en"
    ? `${name}: savings ${inr(savings)}. This month: ₹${g.rules.monthlySaving} ${paidText}. ${loanText} Group has ${inr(state.cash)}.`
    : `${name}: बचत ${inr(savings)}। इस महीने: ₹${g.rules.monthlySaving} ${paidText}। ${loanText} समूह के पास ${inr(state.cash)} है।`;
}

/** Group summary. */
function groupSummary(g: Group, month: string, lang: "en" | "hi"): string {
  const state = computeState(g, month);
  const appLoanAmt = state.loans
    .filter((l) => l.status === "approved")
    .reduce((sum, l) => sum + l.principalOutstanding, 0);
  const appLoanCount = state.loans.filter((l) => l.status === "approved").length;
  const unpaidMembers = g.members
    .filter((m) => state.members[m.id]?.paidThisMonth === false)
    .map((m) => (lang === "en" ? m.name : m.nameHi))
    .join(", ");

  return lang === "en"
    ? `Cash in hand: ${inr(state.cash)}. Total savings: ${inr(state.totalSavings)}. Loans out: ${appLoanCount} (${inr(appLoanAmt)} still to come back). Not paid this month: ${unpaidMembers || "none"}.`
    : `हाथ में नकद: ${inr(state.cash)}। कुल बचत: ${inr(state.totalSavings)}। बाहर उधार: ${appLoanCount} (${inr(appLoanAmt)} वापस आना बाकी)। इस महीने नहीं दिया: ${unpaidMembers || "कोई नहीं"}।`;
}

/** Apply an event, returning a new Group. Throws if invalid. */
function applyEvent(g: Group, ev: Ev): Group {
  const byMember = g.members.find((m) => m.id === ev.by);
  if (!byMember) throw new Error(`Recorder ${ev.by} not found.`);

  if (ev.type === "contribution") {
    if (ev.amount <= 0) throw new Error("Contribution amount must be positive.");
    const member = g.members.find((m) => m.id === ev.memberId);
    if (!member) throw new Error(`Member ${ev.memberId} not found.`);
    return { ...g, events: [...g.events, ev] };
  }

  if (ev.type === "loan_request") {
    const check = checkLoan(g, ev.memberId, ev.amount, ev.tenureMonths, ev.month);
    if (!check.ok) {
      throw new Error(check.problems.map((p) => p.en).join(" "));
    }
    return { ...g, events: [...g.events, ev] };
  }

  if (ev.type === "loan_approve") {
    const member = g.members.find((m) => m.id === ev.by);
    if (!member || (member.role !== "leader" && member.role !== "treasurer")) {
      throw new Error(`Only leader/treasurer can approve. ${ev.by} is not eligible.`);
    }
    const loanReq = g.events.find(
      (e) =>
        e.type === "loan_request" &&
        (e as any).loanId === ev.loanId
    ) as any;
    if (!loanReq) throw new Error(`Loan request ${ev.loanId} not found.`);
    if (loanReq.memberId === ev.by) throw new Error("Borrower cannot approve own loan.");
    const state = computeState(g, ev.month);
    const loan = state.loans.find((l) => l.loanId === ev.loanId);
    if (!loan) throw new Error(`Loan ${ev.loanId} not found.`);
    if (loan.status !== "pending") throw new Error(`Loan ${ev.loanId} is not pending.`);
    if (loan.approvals.includes(ev.by)) throw new Error(`${ev.by} already approved this loan.`);
    return { ...g, events: [...g.events, ev] };
  }

  if (ev.type === "loan_reject") {
    const member = g.members.find((m) => m.id === ev.by);
    if (!member || (member.role !== "leader" && member.role !== "treasurer")) {
      throw new Error(`Only leader/treasurer can reject. ${ev.by} is not eligible.`);
    }
    const loanReq = g.events.find(
      (e) =>
        e.type === "loan_request" &&
        (e as any).loanId === ev.loanId
    ) as any;
    if (!loanReq) throw new Error(`Loan request ${ev.loanId} not found.`);
    const state = computeState(g, ev.month);
    const loan = state.loans.find((l) => l.loanId === ev.loanId);
    if (!loan) throw new Error(`Loan ${ev.loanId} not found.`);
    if (loan.status !== "pending") throw new Error(`Loan ${ev.loanId} is not pending.`);
    return { ...g, events: [...g.events, ev] };
  }

  if (ev.type === "repayment") {
    if (ev.amount <= 0) throw new Error("Repayment amount must be positive.");
    const state = computeState(g, ev.month);
    const loan = state.loans.find((l) => l.loanId === ev.loanId);
    if (!loan) throw new Error(`Loan ${ev.loanId} not found.`);
    if (loan.status !== "approved") throw new Error(`Loan ${ev.loanId} is not approved.`);
    const maxRepay = (loan.nextDue?.interest || 0) + loan.principalOutstanding;
    if (ev.amount > maxRepay) throw new Error(`Repayment exceeds outstanding+interest.`);
    return { ...g, events: [...g.events, ev] };
  }

  throw new Error(`Unknown event type.`);
}

// ===== EXPORTS =====
export {
  monthsBetween,
  addMonths,
  inr,
  computeState,
  checkLoan,
  balanceText,
  groupSummary,
  applyEvent,
};
export type {
  Role,
  Member,
  Rules,
  Ev,
  Group,
  LoanView,
  ComputedState,
  CheckLoanResult,
};
